import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { ArrowClockwise, ArrowDown, ArrowRight, ArrowSquareOut, ArrowUpRight, ArrowsLeftRight, BookOpen, Bug, CaretDown, CaretLeft, CaretRight, ChartBar, Check, CheckCircle, CircleNotch, ClipboardText, Database, DownloadSimple, Flask, FolderOpen, GearSix, GithubLogo, Headset, Info, Kanban, Lightbulb, List, MagnifyingGlass, Moon, Palette, PaperPlaneTilt, PencilSimple, Play, Plus, ShieldCheck, Sparkle, SquaresFour, Star, Sun, Target, ThumbsDown, ThumbsUp, WarningCircle, X } from '@phosphor-icons/react';
import { Badge, Button, DateText, Empty, ExternalLink, Modal, Panel, PanelHead, SearchInput, Status, number } from './ui';
import { palettes, useAppearance } from './appearance';
import type { Action, Conversation, Dataset, DatasetPreview, Knowledge, Page, Run, Sample, State, Uat } from './supportTypes';
import { TraceView } from './TraceView';
import { traceConversationUrl } from './tracePresentation';
import { DialogueKnowledge } from './DialogueKnowledge';
import { DatasetProjects } from './DatasetProjects';
import { AgentLab } from './AgentLab';
import { EvaluationWorkspace } from './EvaluationWorkspace';
import { ExperienceDashboard } from './ExperienceDashboard';
import { QuickStart } from './QuickStart';
import { ModelOps } from './ModelOps';
import { ConnectionModal } from './ModelConnection';
import { rememberedRun, runFromHash, runUrl } from './labNavigation';
import { ChatsCircle } from '@phosphor-icons/react';
import './traces.css';

const routes: { id: Page; name: string; icon: typeof SquaresFour; advanced?: boolean }[] = [
  { id: 'datasets', name: '项目集', icon: FolderOpen },
  { id: 'benchmark', name: '运行评测', icon: Flask },
  { id: 'overview', name: '结果大盘', icon: SquaresFour },
  { id: 'compare', name: '模型对比', icon: ArrowsLeftRight },
  { id: 'modelops', name: '模型运营', icon: ShieldCheck },
  { id: 'guide', name: '使用说明', icon: BookOpen },
  { id: 'playground', name: '客服试聊', icon: Headset, advanced: true },
  { id: 'models', name: '模型连接', icon: GearSix, advanced: true },
  { id: 'knowledge', name: '对话知识库', icon: BookOpen, advanced: true },
  { id: 'traces', name: '执行记录 Trace', icon: ArrowsLeftRight, advanced: true },
  { id: 'settings', name: '工作区设置', icon: GearSix, advanced: true },
];
const routeFromHash = (): Page => {
  const route = location.hash.slice(1).split('?')[0];
  if (route === 'runs' || route === 'badcases') return 'benchmark';
  if (route === 'actions' || route === 'sources') return route;
  return routes.find(value => value.id === route)?.id || 'datasets';
};
class ApiError extends Error { traceId?: string; }
async function api<T>(path: string, payload?: unknown): Promise<T> {
  const response = await fetch(`/api/support${path}`, payload === undefined ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
  if (!response.ok) { const error = await response.json().catch(() => null); const problem = new ApiError(error?.error || `服务返回 ${response.status}`); problem.traceId = error?.traceId; throw problem; }
  return response.json();
}
function exportRun(run: Run, file: string) { const anchor = document.createElement('a'); anchor.href = `/api/support/runs/${run.id}/${file}`; anchor.download = `${run.id}-${file}`; anchor.click(); }
const format = (value?: number) => value === undefined ? '未评测' : value.toFixed(2);
const datasetShort = (id: string) => id === 'bitext' ? 'Bitext · 电商客服' : 'BANKING77 · 外部参照';
const label = (state: State, intent: string) => state.intentLabels[intent] || intent.replaceAll('_', ' ');

export default function SupportApp() {
  const [page, setPage] = useState<Page>(routeFromHash);
  const [state, setState] = useState<State | null>(null);
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [mobile, setMobile] = useState(false);
  const [appearanceOpen, setAppearanceOpen] = useState(false);
  const [guideOpen, setGuideOpen] = useState(false);
  const [connectionOpen, setConnectionOpen] = useState(false);
  const [newRun, setNewRun] = useState(false);
  const [runDataset, setRunDataset] = useState('bitext');
  const [selectedRunId, setSelectedRunId] = useState('');
  const [runDetail, setRunDetail] = useState<Run | null>(null);
  const [preview, setPreview] = useState<Dataset | null>(null);
  const [evidence, setEvidence] = useState<Sample | null>(null);
  const [edit, setEdit] = useState<Knowledge | null>(null);
  const [busy, setBusy] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [uatOpen, setUatOpen] = useState(false);
  const [traceId, setTraceId] = useState<string | null>(() => new URLSearchParams(location.hash.split('?')[1] || '').get('trace'));
  const refresh = useCallback(async () => { try { const value = await api<State>('/state'); setState(value); setError(''); } catch (problem) { setError(problem instanceof Error ? problem.message : '无法连接本地服务'); } }, []);
  useEffect(() => {
    const openConnection = () => {
      const [route, query = ''] = location.hash.slice(1).split('?');
      const params = new URLSearchParams(query);
      if (params.get('connect') !== '1') return;
      setConnectionOpen(true);
      params.delete('connect');
      history.replaceState(history.state, '', `${location.pathname}${location.search}#${route}${params.size ? `?${params}` : ''}`);
    };
    openConnection();
    window.addEventListener('hashchange', openConnection);
    return () => window.removeEventListener('hashchange', openConnection);
  }, []);
  const notify = (message: string) => setToast(message);
  const go = useCallback((next: Page) => { const params = new URLSearchParams(location.hash.split('?')[1]); const vision = params.get('mode') === 'vision' || !!params.get('mmrun'); location.hash = ['overview', 'benchmark', 'compare'].includes(next) ? vision ? `${next}?mode=vision${params.get('mmrun') ? `&mmrun=${encodeURIComponent(params.get('mmrun')!)}` : ''}` : runUrl(next) : next; setPage(next); setMobile(false); window.scrollTo(0, 0); }, []);
  useEffect(() => { void refresh(); const timer = setInterval(() => void refresh(), 2500); return () => clearInterval(timer); }, [refresh]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 5500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const hash = () => { setPage(routeFromHash()); setMobile(false); setTraceId(new URLSearchParams(location.hash.split('?')[1] || '').get('trace')); }; const key = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key === 'k') { event.preventDefault(); setSearchOpen(true); } }; const trace = (event: Event) => { const identifier = (event as CustomEvent<string>).detail; const run = new URLSearchParams(location.hash.split('?')[1]).get('mmrun') || (['overview', 'benchmark', 'compare'].includes(location.hash.slice(1).split('?')[0]) ? rememberedRun() : ''); location.hash = `traces?trace=${encodeURIComponent(identifier)}${run ? `&run=${encodeURIComponent(run)}` : ''}`; setTraceId(identifier); setPage('traces'); window.scrollTo(0,0); }; window.addEventListener('hashchange', hash); window.addEventListener('keydown', key); window.addEventListener('evalpilot:trace', trace); return () => { window.removeEventListener('hashchange', hash); window.removeEventListener('keydown', key); window.removeEventListener('evalpilot:trace', trace); }; }, []);
  const returnTo = new URLSearchParams(location.hash.split('?')[1] || '').get('return') || '';
  const returnOverview = /^overview(?:\?|$)/.test(returnTo) ? returnTo : '';
  const selected = state?.runs.find(run => run.id === selectedRunId) || state?.runs.find(run => run.datasetId === 'bitext' && run.status === 'completed') || state?.runs[0];
  useEffect(() => { if (!selected) return; let active = true; api<Run>(`/runs/${selected.id}`).then(value => { if (active) setRunDetail(value); }).catch(() => { if (active) setRunDetail(null); }); return () => { active = false; }; }, [selected?.id, selected?.status, selected?.completed]);
  const act = async (operation: () => Promise<unknown>, message: string) => { setBusy(true); try { await operation(); await refresh(); notify(message); } catch (problem) { notify(problem instanceof Error ? problem.message : '操作失败，请重试'); } finally { setBusy(false); } };
  const start = (datasetId = 'bitext') => { setRunDataset(datasetId); setNewRun(true); };
  const inspect = (run: Run, target: Page = 'benchmark') => { setSelectedRunId(run.id); go(target); };
  const makeAction = (sample: Sample) => void act(async () => { await api('/actions', { title: `修复意图混淆：${sample.expected} → ${sample.candidate}`, runId: selected?.id, sampleId: sample.id }); setEvidence(null); go('actions'); }, '已关联原始测试样本；同一问题不会重复建任务。');
  const runUat = () => void act(async () => { await api('/uat', {}); setUatOpen(true); }, '已按当前知识库版本执行中文业务回归。');
  if (!state) return <div className="loading-screen"><span className="brand-symbol"><SquaresFour size={28} weight="bold" /></span><h1>EvalPilot</h1><p>{error || '正在读取本地评测工作区…'}</p>{error ? <Button primary onClick={() => void refresh()}>重新连接</Button> : <div className="loading-track" />}</div>;
  const active = state.runs.find(run => run.status === 'running');
  const content: Record<Page, ReactNode> = {
    modelops: <ModelOps corpora={state.corpora} />,
    guide: <QuickStart />,
    overview: <ExperienceDashboard />,
    datasets: <Datasets state={state} preview={setPreview} />,
    benchmark: <EvaluationWorkspace view="runs" corpora={state.corpora} />,
    playground: <AgentLab view="simulate" corpora={state.corpora} />,
    compare: <EvaluationWorkspace view="compare" corpora={state.corpora} />,
    models: <AgentLab view="models" corpora={state.corpora} />,
    knowledge: <DialogueKnowledge policies={<KnowledgeBase state={state} edit={setEdit} runUat={runUat} busy={busy} showUat={() => setUatOpen(true)} />} notify={notify} changed={refresh} resume={identifier => { sessionStorage.setItem('evalpilot.chat.session', identifier); go('playground'); }} />,
    badcases: <EvaluationWorkspace view="runs" corpora={state.corpora} />,
    actions: <Actions state={state} busy={busy} update={(action, verify) => void act(() => api(`/actions/${action.id}${verify ? '/verify' : ''}`, verify ? {} : { status: action.status === 'todo' ? 'progress' : 'todo' }), verify ? '已执行样本回归；请查看实际验收结果。' : '任务状态已保存。')} />,
    sources: <Sources state={state} />,
    settings: <Settings state={state} />,
    traces: <TraceView traceId={traceId} choose={identifier => { setTraceId(identifier); setPage('traces'); const params = new URLSearchParams(location.hash.split('?')[1] || ''); if (identifier) params.set('trace', identifier); else params.delete('trace'); location.hash = `traces${params.size ? `?${params}` : ''}`; window.scrollTo(0,0); }} run={identifier => { if (identifier.startsWith('MMRUN-')) { location.hash = `compare?mode=vision&mmrun=${encodeURIComponent(identifier)}`; setPage('compare'); } else if (identifier.startsWith('EVAL-')) { location.hash = `benchmark?run=${encodeURIComponent(identifier)}`; setPage('benchmark'); } else { setSelectedRunId(identifier); go('benchmark'); } }} conversation={identifier => { setPage('knowledge'); location.hash = traceConversationUrl(identifier, location.hash); window.scrollTo(0,0); }} notify={notify} changed={refresh} />,
  };
  return <div className="app-shell">
    {mobile && <div className="nav-scrim" onClick={() => setMobile(false)} />}
    <aside className={`sidebar ${mobile ? 'open' : ''}`}>
      <a className="brand" href="#datasets" onClick={() => go('datasets')}><span className="brand-symbol"><SquaresFour size={23} weight="bold" /></span><span>EvalPilot<small>模型评测与运营</small></span></a>
      <button className="workspace" onClick={() => go('settings')}><span className="workspace-icon">E</span><span>评测工作区<small>项目管理 · 评测与运营</small></span><CaretDown size={13} /></button>
      <nav aria-label="主导航">{routes.filter(route => !route.advanced).map(route => <button key={route.id} className={`nav-item ${page === route.id ? 'active' : ''}`} aria-current={page === route.id ? 'page' : undefined} onClick={() => go(route.id)}><route.icon size={19} /><span>{route.name}</span></button>)}</nav>
      <details className="secondary-navigation" key={routes.find(route => route.id === page)?.advanced ? 'advanced' : 'main'} open={routes.find(route => route.id === page)?.advanced || undefined}><summary>更多工具<CaretDown size={14} /></summary><nav aria-label="更多工具">{routes.filter(route => route.advanced).map(route => <button key={route.id} className={`nav-item ${page === route.id ? 'active' : ''}`} aria-current={page === route.id ? 'page' : undefined} onClick={() => go(route.id)}><route.icon size={18} /><span>{route.name}</span></button>)}</nav></details>
      <div className="sidebar-bottom"><div className="workspace-health"><span className="health-dot" /><strong>本地引擎已就绪</strong><p>本地训练 · 外部调用须确认</p><button onClick={() => go('guide')}>如何开始使用 <ArrowUpRight size={13} /></button></div><div className="profile"><span>评</span><div>评测团队<small>Local workspace</small></div><ShieldCheck size={18} /></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button menu-toggle" aria-label="打开导航" onClick={() => setMobile(true)}><List size={21} /></button><span>模型评测</span><CaretRight size={13} /><strong>{routes.find(route => route.id === page)?.name}</strong></div><div className="topbar-actions"><button className="appearance-shortcut" onClick={() => setConnectionOpen(true)} aria-label="连接模型 / API Key"><Plus size={18} /><span>连接模型</span></button><button className="appearance-shortcut" onClick={() => setGuideOpen(true)} aria-label="打开使用说明"><BookOpen size={18} /><span>使用说明</span></button><button className="appearance-shortcut" onClick={() => setAppearanceOpen(true)} aria-label="修改配色"><Palette size={18} /><span>外观</span></button><span className="top-avatar">评</span></div></header>
      <main className="main-content">{error && <div className="notice error" role="alert"><WarningCircle size={18} /><span>{error}。当前显示上次读取的数据。</span><button onClick={() => void refresh()}>重试</button></div>}{active && page !== 'benchmark' && <button className="active-run-bar" onClick={() => inspect(active)}><CircleNotch size={17} className="spin" /><span>{datasetShort(active.datasetId)} · {active.stage}</span><strong>查看进度 <ArrowRight size={14} /></strong></button>}{page === 'knowledge' && /^traces(?:\?|$)/.test(returnTo) && <div className="workflow-return"><a className="text-link" href={`#${returnTo}`}><CaretLeft size={15} />返回执行记录</a></div>}{page === 'knowledge' && !returnOverview && !/^traces(?:\?|$)/.test(returnTo) && runFromHash() && <div className="workflow-return"><a className="text-link" href={runFromHash().startsWith('MMRUN-') ? `#compare?mode=vision&mmrun=${encodeURIComponent(runFromHash())}` : runUrl('benchmark', runFromHash())}><CaretLeft size={15} />返回本批评测</a></div>}{content[page]}<footer className="page-footer"><span><ShieldCheck size={13} />外部模型仅确认后调用 · 业务动作仅沙箱</span><button onClick={() => go('guide')}>使用说明与能力边界 <ArrowUpRight size={13} /></button></footer></main>
    </div>
    {toast && <div className="toast" role="status"><Info size={18} /><span>{toast}</span><button onClick={() => setToast('')} aria-label="关闭提示"><X size={16} /></button></div>}
    <ConnectionModal open={connectionOpen} connection={null} close={() => setConnectionOpen(false)} changed={refresh} />
    <Modal open={guideOpen} onClose={() => setGuideOpen(false)} title="使用说明" description="按步骤体验，关闭后继续当前操作。" wide><QuickStart compact onNavigate={() => setGuideOpen(false)} /></Modal>
    <Modal open={appearanceOpen} onClose={() => setAppearanceOpen(false)} title="把工作区调成你喜欢的样子" description="主题色与明暗模式立即生效，刷新后也会保留。"><AppearanceControls /></Modal>
    <NewExperiment open={newRun} close={() => setNewRun(false)} datasetId={runDataset} state={state} submit={async datasetId => { const run = await api<Run>('/runs', { datasetId }); await refresh(); setNewRun(false); inspect(run); notify('已启动实际训练 / 推理，结果来自独立测试集。'); }} />
    <DatasetBrowser dataset={preview} close={() => setPreview(null)} state={state} />
    <Evidence sample={evidence} run={selected} state={state} close={() => setEvidence(null)} makeAction={makeAction} />
    <KnowledgeEditor policy={edit} close={() => setEdit(null)} submit={async (policy, content) => { await api(`/knowledge/${policy.id}`, { content, version: policy.version }); setEdit(null); await refresh(); notify('知识库新版本已保存。请重新运行中文业务回归。'); }} />
    <Modal open={uatOpen} onClose={() => setUatOpen(false)} title="中文客服业务回归" description="自编验收用例，校验引用、业务边界与转人工路径；不宣称是独立中文 Benchmark。" wide>{state.uat ? <div><div className="uat-summary"><strong>{state.uat.passed}<span> / {state.uat.total}</span></strong><div><h3>{state.uat.passed === state.uat.total ? '当前运行全部通过' : '当前运行仍有失败用例'}</h3><p><DateText value={state.uat.createdAt} /> · 知识快照 #{state.uat.knowledgeHash.slice(0,10)}</p></div></div><div className="uat-list">{state.uat.tests.map(test => <details key={test.id}><summary><Badge tone={test.passed ? 'green' : 'red'}>{test.passed ? '通过' : '失败'}</Badge><span>{test.text}</span><code>{test.id}</code><CaretDown size={15} /></summary><div className="content-box">{test.answer}</div><p>知识命中：{test.assertions.source ? '正确' : '失败'} · 转人工路径：{test.assertions.handoff ? '正确' : '失败'} · 边界表述：{test.assertions.boundary ? '完整' : '缺失'}</p></details>)}</div></div> : <Empty title="尚未执行业务回归" action={<Button primary onClick={runUat}>现在运行</Button>} />}</Modal>
    <Modal open={searchOpen} onClose={() => setSearchOpen(false)} title="搜索工作区" description="快速进入功能页面"><SearchInput value={search} onChange={setSearch} placeholder="输入功能名称" /><div className="command-results">{routes.filter(route => route.name.includes(search)).map(route => <button key={route.id} onClick={() => { go(route.id); setSearchOpen(false); setSearch(''); }}><route.icon size={20} /><span>{route.name}</span><ArrowRight size={16} /></button>)}{routes.filter(route => route.name.includes(search)).length === 0 && <Empty title="未找到对应功能" description="试试“项目”“模型”或“使用说明”。" />}</div></Modal>
  </div>;
}

function Heading({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: ReactNode }) { return <div className="page-head"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div><div className="page-actions">{actions}</div></div>; }
function TraceLink({ id }: { id?: string }) { return id ? <button className="trace-entry-button" onClick={() => window.dispatchEvent(new CustomEvent('evalpilot:trace', { detail: id }))}><ArrowsLeftRight size={14} />查看执行 Trace <ArrowUpRight size={12} /></button> : null; }

function Overview({ state, go, start, inspect, runUat, busy }: { state: State; go: (page: Page) => void; start: () => void; inspect: (run: Run, page?: Page) => void; runUat: () => void; busy: boolean }) {
  const latest = state.datasets.map(dataset => ({ dataset, run: state.runs.find(run => run.datasetId === dataset.id && run.status === 'completed') }));
  const count = state.datasets.reduce((sum, dataset) => sum + dataset.count, 0);
  const tests = state.datasets.reduce((sum, dataset) => sum + dataset.splits.test, 0);
  const staleUat = state.uat && state.knowledge.some(policy => state.uat?.versions[policy.id] !== policy.version);
  const cards = [{ title: '已接入公开样本', value: number(count), suffix: '条', icon: Database, note: '2 个公开数据集 · 可追溯来源' }, { title: '独立测试样本', value: number(tests), suffix: '条', icon: ShieldCheck, note: '不参与训练和阈值选择' }, { title: '业务知识条目', value: String(state.knowledge.length).padStart(2, '0'), suffix: '条', icon: BookOpen, note: '订单 / 物流 / 退款 / 安全' }, { title: '中文业务回归', value: state.uat ? `${state.uat.passed}/${state.uat.total}` : '未运行', suffix: '', icon: CheckCircle, note: staleUat ? '知识已更新，需要重跑' : '自编验收集 · 不是中文基准' }];
  return <><Heading eyebrow="CUSTOMER SUPPORT EVALUATION" title="让客服的每一次回答，都值得信任。" description="用真实数据验证意图，用业务知识约束回答，用失败样本推动下一次改进。" actions={<><Button onClick={() => go('playground')}><Headset size={17} />体验智能客服</Button><Button primary onClick={() => start()}><Plus size={17} />新建评测</Button></>} />
    <div className="context-row"><span><span className="health-dot" />本地训练引擎在线</span><span className="context-divider" /><span>业务场景 <strong>电商售后客服</strong></span><Badge tone="blue">数据快照 · 2026.10.10</Badge><button onClick={() => go('sources')}>查看证据与边界 <ArrowUpRight size={13} /></button></div>
    <div className="metrics-grid">{cards.map((card, index) => <Panel className={`metric-card ${index === 0 ? 'accent-card' : ''}`} key={card.title}><div className="metric-label">{card.title}<card.icon size={19} /></div><div className="metric-value">{card.value}<span>{card.suffix}</span></div><div className="metric-note">{card.note}</div></Panel>)}</div>
    <div className="overview-grid"><Panel className="benchmark-panel"><PanelHead title="公开数据集 · 真实评测结果" description="不同数据集分别报告，不混成一个没有业务含义的总分。" action={<button className="text-link" onClick={() => go('benchmark')}>全部实验 <ArrowUpRight size={14} /></button>} /><div className="bench-legend"><span><i className="legend-marker baseline" />词级朴素贝叶斯基线</span><span><i className="legend-marker" />词 + 字符级 SVM 候选</span><small>意图准确率</small></div><div className="benchmark-comparisons">{latest.map(({ dataset, run }) => <div className="benchmark-comparison" key={dataset.id}><div className="benchmark-name"><strong>{dataset.id === 'bitext' ? 'Bitext Customer Support' : 'BANKING77'}</strong><Badge tone={dataset.id === 'bitext' ? 'amber' : 'gray'}>{dataset.nature}</Badge></div>{run?.metrics ? <><div className="comparison-bar"><span>基线</span><div><i className="baseline" style={{ width: `${run.metrics.baseline.accuracy}%` }} /></div><strong>{format(run.metrics.baseline.accuracy)}<small>%</small></strong></div><div className="comparison-bar"><span>候选</span><div><i style={{ width: `${run.metrics.candidate.accuracy}%` }} /></div><strong>{format(run.metrics.candidate.accuracy)}<small>%</small></strong></div><div className="benchmark-caption"><span>独立测试 {number(run.metrics.candidate.total)} 条 · Macro F1 {format(run.metrics.candidate.macroF1)}</span><button onClick={() => inspect(run)}>查看实验 <ArrowRight size={13} /></button></div></> : <Empty title="尚未运行" action={<Button onClick={start}>开始评测</Button>} />}</div>)}</div><div className="panel-notice"><Info size={15} /><span>Bitext 合成语料的模板相似性会让分数偏乐观；这些分数仅衡量英文意图分类，不能代替生产客服解决率。</span></div></Panel>
      <Panel className="playground-entry"><div className="entry-illustration"><Headset size={30} weight="duotone" /><span>SUPPORT SANDBOX</span></div><h2>别只看分数，<br />亲自问问客服。</h2><p>订单取消、物流查询、退款进度。<br />每条答复都有可检查的知识来源。</p><div className="mini-chat"><span>退款一直没到账，怎么办？</span><div><span className="mini-bot"><Headset size={14} /></span><p>先查看售后进度，不承诺未核实的到账时间。<small><BookOpen size={11} />引用 KB-004 · 当前知识版本</small></p></div></div><Button primary onClick={() => go('playground')}>打开客服试用台 <ArrowRight size={17} /></Button><small className="entry-footnote">检索 / 规则答复，无真实交易权限</small></Panel></div>
    <div className="overview-bottom"><Panel><PanelHead title="从发现问题到验证改进" action={<button className="text-link" onClick={() => go('actions')}>优化任务 <ArrowUpRight size={14} /></button>} /><div className="workflow-steps">{[{ title: '准备业务数据', text: '检查来源、许可与拆分', icon: Database, page: 'datasets' }, { title: '运行独立评测', text: '保留指标与逐条证据', icon: Flask, page: 'benchmark' }, { title: '定位失败样本', text: '检查意图混淆与路由', icon: Bug, page: 'badcases' }, { title: '回归验证', text: '不靠移动卡片宣告成功', icon: CheckCircle, page: 'actions' }].map((step, index) => <button onClick={() => go(step.page as Page)} key={step.title}><span className="step-icon"><step.icon size={19} /></span><small>0{index + 1}</small><strong>{step.title}</strong><p>{step.text}</p></button>)}</div></Panel><Panel className="readiness-panel"><PanelHead title="业务落地检查" /><ul><li><CheckCircle size={16} />公开数据与独立测试<span>已运行</span></li><li><CheckCircle size={16} />中文规则与知识回归<span>{state.uat ? `${state.uat.passed}/${state.uat.total}` : '待运行'}</span></li><li><WarningCircle size={16} />企业真实数据 / 正式政策<span>{state.corpora.length ? '语料已导入 / 政策待审核' : '待接入'}</span></li><li><WarningCircle size={16} />订单 / 工单系统<span>未连接</span></li></ul><button className="readiness-action" onClick={runUat} disabled={busy}><ArrowClockwise size={14} />{staleUat ? '知识已变更，重新验证' : '运行中文业务回归'}<ArrowRight size={14} /></button></Panel></div>
  </>;
}

function Datasets({ state, preview }: { state: State; preview: (dataset: Dataset) => void }) {
  return <DatasetProjects corpora={state.corpora} references={state.datasets} preview={preview} />;
}

function RunSelector({ state, selected, choose }: { state: State; selected?: Run; choose: (id: string) => void }) { return <select className="select run-select" aria-label="选择评测实验" value={selected?.id || ''} onChange={event => choose(event.target.value)}>{state.runs.map(run => <option key={run.id} value={run.id}>{datasetShort(run.datasetId)} · {run.id}</option>)}</select>; }

function Benchmarks({ state, selected, detail, choose, start, evidence, inspect, cancel }: { state: State; selected?: Run; detail: Run | null; choose: (id: string) => void; start: (id?: string) => void; evidence: (sample: Sample) => void; inspect: (run: Run, page?: Page) => void; cancel: (run: Run) => void }) {
  const run = detail?.id === selected?.id ? detail : selected;
  const candidate = run?.metrics?.candidate, baseline = run?.metrics?.baseline;
  return <><Heading eyebrow="REPRODUCIBLE EXPERIMENTS" title="不是预设的分数，是实际执行的实验。" description="用同一独立测试集比较基线与候选，保存错误预测、统计方法和数据版本。" actions={<Button primary onClick={() => start()}><Plus size={16} />新建评测</Button>} /><div className="experiment-toolbar"><RunSelector state={state} selected={selected} choose={choose} />{selected && <Status status={selected.status} />}<TraceLink id={run?.traceId} />{run?.status === 'completed' && <button className="text-link" onClick={() => exportRun(run, 'report.md')}><DownloadSimple size={16} />导出完整报告</button>}</div>
    {!run ? <Empty title="尚无评测实验" action={<Button primary onClick={() => start()}>运行首个实验</Button>} /> : run.status !== 'completed' ? <Panel className="execution-panel"><span className={`execution-icon ${run.status === 'running' ? 'spin' : ''}`}>{run.status === 'running' ? <CircleNotch size={32} /> : <WarningCircle size={32} />}</span><h2>{run.stage}</h2><p>{run.completed} / {run.total} 次测试推理</p><div className="execution-progress"><i style={{ width: `${run.total ? run.completed / run.total * 100 : 0}%` }} /></div>{run.status === 'running' ? <Button onClick={() => cancel(run)}>取消本次运行</Button> : <Button primary onClick={() => start(run.datasetId)}>重新运行</Button>}</Panel> : <>
      <div className={`notice ${run.datasetId === 'bitext' ? 'amber' : ''}`}><Info size={19} /><span>{run.datasetId === 'bitext' ? 'Bitext 是混合合成语料，模板近义改写可能让分数偏乐观。本结果不能代表真实中文客服、生成质量或业务解决率。' : 'BANKING77 使用官方英文测试集，只衡量闭集意图分类。本系统不是金融服务，也没有调用或训练大语言模型。'}</span></div>
      <div className="result-kpis">{[{ title: '意图识别准确率', value: candidate?.accuracy, baseline: baseline?.accuracy, suffix: '%' }, { title: 'Macro F1', value: candidate?.macroF1, baseline: baseline?.macroF1, suffix: '/100' }, { title: 'Top-3 命中率', value: candidate?.top3, baseline: baseline?.top3, suffix: '%' }, { title: '候选失败样本', value: candidate?.failed, baseline: baseline?.failed, suffix: '条', integer: true }].map(card => <Panel key={card.title} className="result-kpi"><span>{card.title}</span><strong>{card.integer ? number(card.value || 0) : format(card.value)}<small>{card.suffix}</small></strong><p>基线 {card.integer ? number(card.baseline || 0) : format(card.baseline)}{card.integer ? ' 条' : ''}</p></Panel>)}</div>
      <div className="interval-note"><ChartBar size={19} /><p>配对准确率变化 <strong>{(run.comparison?.delta || 0) >= 0 ? '+' : ''}{run.comparison?.delta} 个百分点</strong><span>95% 区间 [{run.comparison?.interval.join(', ')}] · 配对 bootstrap 1,000 次 / seed 42</span></p><Badge>{number(candidate?.total || 0)} 对测试样本</Badge></div>
      <div className="experiment-grid"><Panel><PanelHead title="最值得修复的意图混淆" description="来自候选模型的实际错误预测，不是手写的预设问题。" action={<button className="text-link" onClick={() => inspect(run, 'badcases')}>全部失败样本 <ArrowRight size={14} /></button>} />{run.confusions?.length ? <div className="confusion-list">{run.confusions.slice(0,6).map(item => <div key={`${item.expected}-${item.actual}`}><span><strong>{label(state, item.expected)}</strong><small>{item.expected}</small></span><ArrowRight size={16} /><span><strong>{label(state, item.actual)}</strong><small>{item.actual}</small></span><Badge tone="amber">{item.count} 条</Badge></div>)}</div> : <Empty title="测试集没有错误预测" description="这仅说明当前测试集，不证明所有业务场景都正确。" />}</Panel><Panel className="routing-panel"><PanelHead title="低分差转人工策略" description="阈值在验证集上选择，不使用测试答案调参。" /><div className="routing-score">{format(run.routing?.coverage)}<span>%</span><small>建议自动路由覆盖率</small></div><dl><div><dt>被接受样本的意图准确率</dt><dd>{run.routing?.accuracy === null ? '无样本' : `${format(run.routing?.accuracy)}%`}</dd></div><div><dt>建议转人工 / 待确认</dt><dd>{run.routing?.deferred} 条</dd></div><div><dt>分类分差阈值</dt><dd>{run.calibration?.threshold.toFixed(4)}</dd></div></dl><p className="routing-boundary">分类分差不是概率。此处不是自动解决率，未验证域外拒识或生产 SLA。</p></Panel></div>
      <Panel className="protocol-panel"><PanelHead title="可复现配置" action={<div className="row-actions"><button className="text-link" onClick={() => exportRun(run, 'results.csv')}><DownloadSimple size={14} />逐条结果</button><button className="text-link" onClick={() => exportRun(run, 'config.json')}><DownloadSimple size={14} />复现配置</button></div>} /><div className="protocol-facts"><div><span>基线</span><strong>{run.protocol?.models.baseline}</strong></div><div><span>候选</span><strong>{run.protocol?.models.candidate}</strong></div><div><span>训练 / 测试归一化重复</span><strong>{run.protocol?.leakage.trainTest} 条</strong></div><div><span>训练耗时</span><strong>{run.protocol?.trainSeconds}s {run.protocol?.cacheHit ? '· 本次复用相同指纹缓存' : '· 本机实测'}</strong></div><div><span>候选批推理 P95</span><strong>{candidate?.batchP95Ms} ms / 批（最多128条）</strong></div><div><span>数据指纹 SHA-256</span><code>{run.dataset?.sha256.slice(0,24)}…</code></div></div></Panel>
      <Panel className="sample-panel"><PanelHead title="逐条结果预览" description="点击查看输入、标准标签、预测与建议路由。" /><div className="table-wrap"><table><thead><tr><th>测试问题</th><th>标准意图</th><th>候选预测</th><th>结果</th><th /></tr></thead><tbody>{detail?.id === run.id && detail.results?.slice(0,8).map(sample => <tr key={sample.id}><td className="sample-text">{sample.text}<small>{sample.id}</small></td><td>{label(state, sample.expected)}</td><td>{label(state, sample.candidate)}</td><td><Badge tone={sample.passed ? 'green' : 'red'}>{sample.passed ? '正确' : '错误'}</Badge></td><td><button className="icon-button" aria-label={`查看样本 ${sample.id}`} onClick={() => evidence(sample)}><ArrowUpRight size={17} /></button></td></tr>)}</tbody></table></div></Panel>
    </>}
  </>;
}

function Badcases({ state, selected, detail, choose, evidence, makeAction }: { state: State; selected?: Run; detail: Run | null; choose: (id: string) => void; evidence: (sample: Sample) => void; makeAction: (sample: Sample) => void }) {
  const [query, setQuery] = useState(''); const [intent, setIntent] = useState('all'); const [page, setPage] = useState(1);
  const failures = detail?.id === selected?.id ? detail?.results?.filter(sample => !sample.passed) || [] : [];
  const intents = [...new Set(failures.map(sample => sample.expected))];
  const filtered = failures.filter(sample => (intent === 'all' || sample.expected === intent) && `${sample.text}${sample.expected}${sample.candidate}`.toLowerCase().includes(query.toLowerCase()));
  useEffect(() => { setPage(1); }, [query, intent, selected?.id]);
  return <><Heading eyebrow="FAILURE ANALYSIS" title="分数之外，看看客服具体错在哪里。" description="错误意图、混淆方向和参考标签一目了然；每条问题都能沉淀成优化任务。" /><div className="experiment-toolbar"><RunSelector state={state} selected={selected} choose={choose} /><Badge tone="amber">{failures.length} 条候选错误</Badge></div><Panel><div className="table-toolbar"><SearchInput value={query} onChange={setQuery} placeholder="搜索问题或意图" /><select className="select" aria-label="按标准意图筛选" value={intent} onChange={event => setIntent(event.target.value)}><option value="all">所有标准意图</option>{intents.map(item => <option key={item} value={item}>{label(state, item)}</option>)}</select></div>{filtered.length ? <div className="failure-list">{filtered.slice((page-1)*12,page*12).map(sample => <div key={sample.id} className="failure-item"><div className="failure-meta"><code>{sample.id}</code><Badge tone={sample.baselinePassed ? 'red' : 'amber'}>{sample.baselinePassed ? '候选回退' : '双方错误'}</Badge>{sample.defer && <Badge>建议转人工</Badge>}</div><button className="failure-title" onClick={() => evidence(sample)}>{sample.text}<ArrowUpRight size={16} /></button><div className="failure-labels"><span>标准 <strong>{label(state, sample.expected)}</strong></span><ArrowRight size={14} /><span>预测 <strong>{label(state, sample.candidate)}</strong></span></div><div className="failure-bottom"><span>分类分差 {sample.margin.toFixed(4)} · 原始行 {sample.sourceRow}</span><div className="row-actions"><button className="text-link" onClick={() => evidence(sample)}>查看证据</button><Button onClick={() => makeAction(sample)}><Plus size={14} />优化任务</Button></div></div></div>)}</div> : <Empty title="当前没有匹配的错误样本" description={selected?.status === 'running' ? '等待评测完成后展示。' : '试试切换数据集或调整筛选条件。'} />}<Pagination page={page} total={filtered.length} pageSize={12} change={setPage} /></Panel></>;
}

function Playground({ state, refresh, notify, go }: { state: State; refresh: () => Promise<void>; notify: (message: string) => void; go: (page: Page) => void }) {
  const [sessionId, setSessionId] = useState<string | null>(() => sessionStorage.getItem('evalpilot.chat.session'));
  const [query, setQuery] = useState(''); const [pending, setPending] = useState(false); const [pendingText, setPendingText] = useState(''); const [error, setError] = useState(''); const [errorTrace, setErrorTrace] = useState<string | undefined>();
  const [selected, setSelected] = useState<string | null>(null); const end = useRef<HTMLDivElement>(null);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [historyError, setHistoryError] = useState('');
  useEffect(() => {
    let active = true;
    setConversations([]); setHistoryError('');
    if (!sessionId) return;
    const load = async () => {
      try { const turns = await api<Conversation[]>(`/sessions/${sessionId}/turns`); if (active) { setConversations(turns); setHistoryError(''); } }
      catch { if (active) setHistoryError('完整历史暂时无法读取，请重试；不会用最近记录冒充整段对话。'); }
    };
    void load();
    const timer = setInterval(() => void load(), 2500);
    return () => { active = false; clearInterval(timer); };
  }, [sessionId]);
  const current = conversations.find(message => message.id === selected) || conversations.at(-1);
  useEffect(() => { end.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }, [conversations.length, pending]);
  const send = async (message = query) => {
    if (!message.trim() || pending) return;
    setPending(true); setPendingText(message); setError(''); setErrorTrace(undefined); setQuery('');
    try { const response = await api<Conversation>('/chat', { message, sessionId }); setSessionId(response.sessionId); sessionStorage.setItem('evalpilot.chat.session', response.sessionId); setSelected(response.id); setConversations(await api<Conversation[]>(`/sessions/${response.sessionId}/turns`)); await refresh(); }
    catch (problem) { setError(problem instanceof Error ? problem.message : '无法获取回答'); setErrorTrace(problem instanceof ApiError ? problem.traceId : undefined); setQuery(message); await refresh(); }
    finally { setPending(false); setPendingText(''); }
  };
  const feedback = async (message: Conversation, value: string) => { try { await api('/feedback', { messageId: message.id, feedback: value }); setConversations(await api<Conversation[]>(`/sessions/${message.sessionId}/turns`)); await refresh(); notify('反馈已保存在本机。'); } catch (problem) { notify(problem instanceof Error ? problem.message : '保存失败'); } };
  const makeAction = async () => { if (!current) return; try { await api('/actions', { title: '客服会话复核', messageId: current.id }); await refresh(); notify('已创建本地复核待办，尚未提交企业工单。'); } catch (problem) { notify(problem instanceof Error ? problem.message : '创建失败'); } };
  return <><Heading eyebrow="SUPPORT PLAYGROUND" title="让客户的问题，得到有依据的回应。" description="中文使用可解释的词条与知识路由；英文使用公开语料训练的意图分类器。所有回答均来自当前知识库。" actions={<><Button onClick={() => { location.hash = sessionId ? `knowledge?session=${sessionId}` : 'knowledge'; }}><BookOpen size={16} />查看完整对话 / 沉淀知识</Button><Button onClick={() => { setSessionId(null); sessionStorage.removeItem('evalpilot.chat.session'); setSelected(null); setError(''); }}>新建匿名会话 <Plus size={16} /></Button></>} />{historyError && <div className="notice error" role="alert">{historyError}</div>}<div className="notice amber compact"><ShieldCheck size={18} /><span>请只输入匿名示例。本工作区没有真实订单、资金或人工坐席权限，不会实际取消、退款或完成转接。</span></div><div className="playground-layout"><Panel className="chat-panel"><div className="chat-header"><span className="chat-bot-icon"><Headset size={20} /></span><div><h2>售后服务助手</h2><p><span className="health-dot" />本地知识路由 · {state.knowledge.length} 条业务知识</p></div><Badge>匿名测试</Badge></div><div className="chat-messages">{!conversations.length && !pending ? <div className="chat-welcome"><span><Headset size={34} weight="duotone" /></span><h2>今天，想测试哪个客服场景？</h2><p>不用相信演示话术，直接看看答案和依据。</p><div className="suggested-questions">{['我想取消订单，可以直接帮我取消吗？','退款一直没到账，该怎么办？','收货地址写错了，可以改地址吗？','I want to cancel my order'].map(question => <button key={question} onClick={() => void send(question)}>{question}<ArrowUpRight size={15} /></button>)}</div><small>这里展示的是知识检索能力，不是大语言模型生成效果。</small></div> : <>{conversations.map(message => <div className="chat-turn" key={message.id}><div className="user-message">{message.message}</div><div className={`assistant-message ${current?.id === message.id ? 'selected' : ''}`} onClick={() => setSelected(message.id)}><span className="assistant-avatar"><Headset size={17} /></span><div><div className="answer-text">{message.answer}</div>{message.source ? <button className="answer-source" onClick={() => setSelected(message.id)}><BookOpen size={13} />{message.source.id} · {message.source.title} · v{message.source.version}<ArrowUpRight size={12} /></button> : <Badge tone="amber">建议人工核实 · 未执行真实转接</Badge>}<div className="answer-feedback"><TraceLink id={message.traceId} /><span>{message.method}</span><button className={message.feedback === 'positive' ? 'active' : ''} aria-label={`认可回答 ${message.id}`} onClick={event => { event.stopPropagation(); void feedback(message, 'positive'); }}><ThumbsUp size={15} /></button><button className={message.feedback === 'negative' ? 'active' : ''} aria-label={`反馈问题 ${message.id}`} onClick={event => { event.stopPropagation(); void feedback(message, 'negative'); }}><ThumbsDown size={15} /></button></div></div></div></div>)}{pending && <div className="chat-turn"><div className="user-message">{pendingText}</div><div className="chat-thinking"><CircleNotch className="spin" size={16} />检查输入并检索知识依据…</div></div>}<div ref={end} /></>}</div><form className="chat-composer" onSubmit={event => { event.preventDefault(); void send(); }}>{error && <div className="form-error" role="alert">{error}</div>}{errorTrace && <div className="trace-request-error"><TraceLink id={errorTrace} /></div>}<div className="composer-field"><textarea aria-label="输入客服问题" value={query} onChange={event => setQuery(event.target.value)} placeholder="输入一个客服问题，勿包含真实姓名、手机号或账号…" maxLength={1000} onKeyDown={event => { if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) { event.preventDefault(); void send(); } }} /><Button primary type="submit" disabled={pending || !query.trim()} title="发送问题"><PaperPlaneTilt size={18} weight="fill" /></Button></div><div className="composer-hint"><span>Enter 发送 · Shift + Enter 换行</span><span><ShieldCheck size={11} />仅保存在本机</span></div></form></Panel><div className="answer-inspector"><Panel><PanelHead title="回答依据" action={<Badge tone="blue">可追溯</Badge>} />{current ? <div className="inspector-body"><TraceLink id={current.traceId} /><span className="inspector-label">意图 / 路由</span><h3>{label(state, current.intent)}</h3><p>{current.method}</p>{current.source ? <div className="citation-card"><BookOpen size={19} /><strong>{current.source.title}</strong><span>{current.source.id} · v{current.source.version}</span><p>{current.source.origin}</p><button onClick={() => go('knowledge')}>查看知识库 <ArrowUpRight size={13} /></button></div> : <div className="notice amber"><Info size={17} />没有足够可靠的知识命中，保守退回人工核实。</div>}{current.inference && <div className="inference-details"><span>候选意图</span>{current.inference.top3.map((intent,index) => <div key={intent}><small>0{index+1}</small>{label(state,intent)}</div>)}<p>分类分差 {current.inference.margin.toFixed(4)}，不是概率。阈值 {current.inference.threshold.toFixed(4)}。</p></div>}<div className="inspector-timing"><span>本地处理耗时</span><strong>{current.latencyMs} ms</strong></div><Button onClick={() => void makeAction()}><Plus size={14} />建立复核待办</Button></div> : <Empty title="发送问题后查看" description="这里会展示命中的知识、版本和路由方式。" />}</Panel><Panel className="sandbox-boundaries"><ShieldCheck size={21} /><h3>有依据，也有边界</h3><ul><li>没有实时订单查询</li><li>没有支付或退款执行权限</li><li>未连接人工坐席或工单系统</li><li>示例政策需企业审核后替换</li></ul></Panel></div></div></>;
}

function KnowledgeBase({ state, edit, runUat, busy, showUat }: { state: State; edit: (policy: Knowledge) => void; runUat: () => void; busy: boolean; showUat: () => void }) {
  const [query, setQuery] = useState(''); const filtered = state.knowledge.filter(policy => `${policy.title}${policy.content}`.includes(query));
  const stale = state.uat && state.knowledge.some(policy => state.uat?.versions[policy.id] !== policy.version);
  return <><div className="section-heading"><h2>可用于客服答复的知识</h2><Button primary onClick={runUat} disabled={busy}><Play size={15} weight="fill" />运行中文回归</Button></div><div className="notice amber"><Info size={19} /><span>初始 8 条为项目示例政策；对话整理知识须经明确审核发布才会出现在这里。原始对话和未审核草稿不会直接用于客服答复。</span></div><div className="knowledge-toolbar"><TraceLink id={state.uat?.traceId} /><SearchInput value={query} onChange={setQuery} placeholder="搜索知识标题或内容" />{state.uat && <button className="text-link" onClick={showUat}><CheckCircle size={16} />上次回归 {state.uat.passed}/{state.uat.total}{stale ? ' · 知识已变更，请重跑' : ' · 与当前版本一致'}<ArrowUpRight size={13} /></button>}</div><div className="knowledge-grid">{filtered.map(policy => <Panel key={policy.id} className="knowledge-card"><div className="knowledge-card-top"><Badge>{policy.category}</Badge><code>{policy.id} / v{policy.version}</code></div><h2>{policy.title}</h2><p>{policy.content}</p>{policy.provenance && <a className="text-link" href={`#knowledge?session=${policy.provenance.sessionId}&archive=${policy.provenance.archiveId}`}><ChatsCircle size={14} />查看完整来源对话 · v{policy.provenance.archiveVersion}<ArrowUpRight size={13} /></a>}<div className="knowledge-keywords">{policy.keywords.slice(0,4).map(word => <span key={word}>{word}</span>)}</div><div className="knowledge-footer"><span><DateText value={policy.updatedAt} /></span><Button onClick={() => edit(policy)}><PencilSimple size={14} />编辑条目</Button></div></Panel>)}</div>{!filtered.length && <Empty />}</>;
}

function Actions({ state, busy, update }: { state: State; busy: boolean; update: (action: Action, verify: boolean) => void }) {
  const columns = [{ id: 'todo', name: '待处理' }, { id: 'progress', name: '优化中' }, { id: 'done', name: '已验证' }];
  return <><Heading eyebrow="CONTINUOUS IMPROVEMENT" title="把真实问题，变成能追踪的改进。" description="关联原始评测样本或本地测试会话。只有真实样本回归正确，任务才能自动验收。" /><div className="notice"><Info size={18} /><span>对冻结测试集的错误分析不会自动把样本加入训练集。若按测试错误调优，应另建时间外测试集，不能继续把同一测试分数当作无偏验收。</span></div><div className="task-board">{columns.map(column => <section key={column.id} className="task-column"><h2><span className={`column-dot ${column.id}`} />{column.name}<small>{state.actions.filter(action => action.status === column.id).length}</small></h2>{state.actions.filter(action => action.status === column.id).map(action => <Panel className="task-card" key={action.id}><div className="task-meta"><code>{action.id}</code><Badge>{action.source.kind === 'benchmark' ? '测试集问题' : '本地会话'}</Badge></div><h3>{action.title}</h3><blockquote>{action.source.text}</blockquote><p>{action.source.kind === 'benchmark' ? `标准意图：${action.source.expected}` : '尚无人工审核标签，不能自动验收。'}</p><div className="task-owner"><span>质</span>{action.owner}</div><TraceLink id={action.source.traceId} />{action.verification && <div className={`task-verification ${action.verification.passed ? 'passed' : ''}`}><strong>{action.verification.passed ? '回归通过' : '仍需优化'}</strong><span>当前预测：{action.verification.actual}</span></div>}<div className="task-buttons">{action.status !== 'done' && <Button onClick={() => update(action, false)} disabled={busy}>{action.status === 'todo' ? '开始处理' : '退回待处理'}</Button>}{action.status === 'progress' && action.source.kind === 'benchmark' && <Button primary onClick={() => update(action, true)} disabled={busy}>验证样本 <ArrowClockwise size={14} /></Button>}{action.status === 'done' && <span><CheckCircle size={16} />已通过实际回归</span>}</div></Panel>)}{!state.actions.some(action => action.status === column.id) && <div className="task-empty">{column.id === 'todo' ? '从失败样本或客服会话创建任务' : column.id === 'done' ? '回归验证通过后出现在这里' : '开始处理后出现在这里'}</div>}</section>)}</div></>;
}

function Sources({ state }: { state: State }) { return <><Heading eyebrow="METHODS & PROVENANCE" title="每份数据、每个分数，都能找到出处。" description="保留公开来源、许可、导入日期与拆分方法；开源项目仅借鉴设计，不冒充已经集成。" /><div className="source-data-list">{state.datasets.map(dataset => <Panel className="source-data" key={dataset.id}><div><span className="eyebrow">DATA SOURCE</span><h2>{dataset.name}</h2><p>{dataset.nature} · {dataset.language} · {dataset.license}</p><div className="row-actions"><ExternalLink href={dataset.source}>发布方原始数据</ExternalLink><a className="text-link" href={`/api/support/licenses/${dataset.id}`} download>下载许可副本 <DownloadSimple size={14} /></a></div></div><dl><div><dt>锁定修订</dt><dd><code>{dataset.revision}</code></dd></div><div><dt>完整性校验</dt><dd><code>{dataset.sha256}</code></dd></div><div><dt>拆分方法</dt><dd>{dataset.splitPolicy}</dd></div><div><dt>加工方式</dt><dd>{dataset.preprocessing}</dd></div></dl></Panel>)}</div><div className="section-heading"><h2>借鉴的开源评测思路</h2><span>GitHub Star 快照 · 2026-10-10</span></div><div className="reference-grid">{state.references.map(reference => <Panel className="reference-card" key={reference.name}><div><GithubLogo size={23} /><span><Star size={14} />{number(reference.stars)}</span></div><h3>{reference.name}</h3><p>{reference.borrowed}</p><ExternalLink href={reference.url}>查看原项目</ExternalLink></Panel>)}</div><Panel className="method-definitions"><PanelHead title="这些指标到底在测什么？" /><div className="table-wrap"><table><thead><tr><th>指标</th><th>定义</th><th>不能代表什么</th></tr></thead><tbody>{[['Accuracy','测试集预测正确条数 / 测试总条数','不等于客服问题解决率'],['Macro F1','各个意图的 F1 等权平均','不是生成内容的人类质量评分'],['Top-3 命中率','正确意图是否出现在前三候选中','不等于前三项都可靠'],['建议路由覆盖率','分类分差超过验证阈值的样本比例','不是自动服务完成率，也未测试域外拒识'],['中文规则回归','自编用例的知识引用、转人工和边界断言','不是独立中文泛化 Benchmark'],['批推理 P95','每批最多128条的本地推理耗时95分位','不是在线单请求P95，也不是LLM响应时间']].map(([metric,definition,boundary]) => <tr key={metric}><td><strong>{metric}</strong></td><td>{definition}</td><td>{boundary}</td></tr>)}</tbody></table></div></Panel></>; }

function AppearanceControls() { const appearance = useAppearance(); return <div className="appearance-controls"><h3>主题色</h3><p>可切换 4 套高对比配色，不再使用浅绿文字。</p><div className="palette-grid">{palettes.map(palette => <button key={palette.id} className={appearance.palette === palette.id ? 'selected' : ''} onClick={() => appearance.update({ palette: palette.id })} aria-pressed={appearance.palette === palette.id}><i style={{ background: palette.color }}>{appearance.palette === palette.id && <Check size={17} />}</i><span>{palette.name}</span></button>)}</div><h3>明暗模式</h3><div className="mode-grid"><button aria-pressed={appearance.mode === 'light'} className={appearance.mode === 'light' ? 'selected' : ''} onClick={() => appearance.update({ mode: 'light' })}><Sun size={22} /><strong>明亮</strong><span>适合会议与日常工作</span></button><button aria-pressed={appearance.mode === 'dark'} className={appearance.mode === 'dark' ? 'selected' : ''} onClick={() => appearance.update({ mode: 'dark' })}><Moon size={22} /><strong>深色</strong><span>适合专注演示与夜间工作</span></button></div><div className="notice"><CheckCircle size={18} />外观设置即时生效，并仅保存在当前浏览器。</div></div>; }

function Settings({ state: _state }: { state: State }) { return <><Heading eyebrow="" title="工作区设置" description="调整阅读配色；模型密钥请在「模型连接」中单独配置。" /><div className="settings-layout"><Panel className="appearance-panel"><PanelHead title="工作区外观" /><AppearanceControls /></Panel><Panel><PanelHead title="当前能力与边界" /><dl className="runtime-details"><div><dt>业务数据</dt><dd>按项目管理已导入的脱敏对话</dd></div><div><dt>本地模型</dt><dd>当前售后基线：行为分类器 + 安全模板，不是大模型微调</dd></div><div><dt>外部模型 / 裁判</dt><dd><a href="#models" className="text-link">管理模型连接</a></dd></div><div><dt>业务操作</dt><dd>仅模拟，不执行真实退款、派单或转人工</dd></div><div><dt>使用范围</dt><dd>本机验证，无多用户权限，不可直接公网发布</dd></div></dl></Panel></div><details className="lab-disclosure"><summary>旧版方法与记录（不纳入当前评测）</summary><p>历史资料与结果均保留，不计入当前评测大盘。</p><div className="lab-row-actions"><a className="text-link" href="#sources">旧版公开评测说明</a><a className="text-link" href="#actions">旧版优化任务</a></div></details></>; }

function NewExperiment({ open, close, datasetId, state, submit }: { open: boolean; close: () => void; datasetId: string; state: State; submit: (id: string) => Promise<void> }) {
  const [dataset, setDataset] = useState(datasetId); const [pending, setPending] = useState(false); const [error, setError] = useState('');
  useEffect(() => { if (open) { setDataset(datasetId); setError(''); } }, [open,datasetId]); const metadata = state.datasets.find(item => item.id === dataset);
  return <Modal open={open} onClose={() => !pending && close()} title="运行一次真实的客服意图评测" description="使用固定训练 / 验证 / 测试拆分，比较基线和候选。无需外部 API 密钥。"><form onSubmit={async event => { event.preventDefault(); setPending(true); setError(''); try { await submit(dataset); } catch (problem) { setError(problem instanceof Error ? problem.message : '无法启动'); } finally { setPending(false); } }}><label className="form-field">评测数据<select value={dataset} onChange={event => setDataset(event.target.value)}>{state.datasets.map(item => <option key={item.id} value={item.id}>{item.name} · {number(item.splits.test)} 条测试</option>)}</select></label><div className="experiment-config"><div><span>基线</span><strong>词级 TF-IDF + 朴素贝叶斯</strong></div><div><span>候选</span><strong>词级 + 字符级 TF-IDF + 线性 SVM</strong></div><div><span>训练 / 验证 / 测试</span><strong>{number(metadata?.splits.train || 0)} / {number(metadata?.splits.validation || 0)} / {number(metadata?.splits.test || 0)}</strong></div><div><span>执行方式</span><strong>本机 CPU · 固定 seed 42</strong></div></div><div className="notice"><ShieldCheck size={19} /><span>首次运行拟合模型，相同数据指纹可复用本机缓存；每次都实际重跑独立测试，不复用预设分数。</span></div>{dataset === 'bitext' && <div className="notice amber"><Info size={18} />混合合成语料的成绩可能偏乐观，不能用来承诺生产客服效果。</div>}{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><Button onClick={close} disabled={pending}>取消</Button><Button primary type="submit" disabled={pending || state.runs.some(run => run.status === 'running')}><Play size={15} weight="fill" />{pending ? '启动中…' : '开始训练与评测'}</Button></div></form></Modal>;
}

function Pagination({ page, total, pageSize, change }: { page: number; total: number; pageSize: number; change: (page: number) => void }) { const pages = Math.max(1, Math.ceil(total / pageSize)); return <div className="pagination"><span>共 {number(total)} 条 · 第 {page} / {pages} 页</span><div><button className="icon-button" aria-label="上一页" disabled={page <= 1} onClick={() => change(page-1)}><CaretLeft size={17} /></button><button className="icon-button" aria-label="下一页" disabled={page >= pages} onClick={() => change(page+1)}><CaretRight size={17} /></button></div></div>; }

function DatasetBrowser({ dataset, close, state }: { dataset: Dataset | null; close: () => void; state: State }) {
  const [preview, setPreview] = useState<DatasetPreview | null>(null); const [split, setSplit] = useState('test'); const [query, setQuery] = useState(''); const [page, setPage] = useState(1); const [intent,setIntent] = useState(''); const [error,setError] = useState(''); const [loading,setLoading] = useState(false);
  useEffect(() => { setSplit('test'); setQuery(''); setPage(1); setIntent(''); setPreview(null); }, [dataset?.id]);
  useEffect(() => { if (!dataset) return; let active = true; setLoading(true); const timer = setTimeout(() => { api<DatasetPreview>(`/datasets/${dataset.id}?${new URLSearchParams({split,q:query,page:String(page),intent})}`).then(value => { if (active) { setPreview(value); setError(''); } }).catch(problem => { if (active) setError(problem.message); }).finally(() => { if (active) setLoading(false); }); }, 160); return () => { active = false; clearTimeout(timer); }; }, [dataset?.id,split,query,page,intent]);
  return <Modal open={!!dataset} onClose={close} title={dataset?.name || '数据浏览'} description={`${dataset?.nature || ''} · 英语原文 · 来源行号可追溯 · ${dataset?.license || ''}`} wide><div className="dataset-browser-tools"><div className="tabs">{[['train','训练集'],['validation','验证集'],['test','测试集']].map(([value,name]) => <button key={value} className={split === value ? 'active' : ''} onClick={() => { setSplit(value); setPage(1); }}>{name}<span>{number(dataset?.splits[value] || 0)}</span></button>)}</div><SearchInput value={query} onChange={value => { setQuery(value); setPage(1); }} placeholder="搜索英文问题或意图" /><select className="select" aria-label="筛选数据集意图" value={intent} onChange={event => { setIntent(event.target.value); setPage(1); }}><option value="">所有意图</option>{preview?.intents.map(value => <option key={value} value={value}>{label(state,value)}</option>)}</select></div>{error && <div className="form-error">{error}</div>}<div className={`dataset-browser-list ${loading ? 'loading' : ''}`}>{preview?.rows.map(row => <div key={row.id}><div><code>{row.id}</code><Badge>{label(state,row.intent)}</Badge></div><p>{row.text}</p><small>{row.sourceFile} · 原始数据行 {row.originalRow} · <code>{row.intent}</code></small></div>)}{preview?.total === 0 && <Empty title="没有匹配的问题" description="可调整英文关键词或意图筛选。" />}{!preview && loading && <div className="inline-loading"><CircleNotch className="spin" size={18} />读取本地数据…</div>}</div><Pagination page={page} total={preview?.total || 0} pageSize={25} change={setPage} /></Modal>;
}

function Evidence({ sample, run, state, close, makeAction }: { sample: Sample | null; run?: Run; state: State; close: () => void; makeAction: (sample: Sample) => void }) { return <Modal open={!!sample} onClose={close} title="样本级评测证据" description={`${run ? datasetShort(run.datasetId) : ''} · 固定测试集 · 原始标签未参与训练`} wide>{sample && <div className="evidence-body"><div className="evidence-meta"><code>{sample.id}</code><Badge tone={sample.passed ? 'green' : 'red'}>{sample.passed ? '候选正确' : '候选错误'}</Badge>{sample.defer && <Badge tone="amber">建议转人工</Badge>}</div><h3>测试问题 · 英语原文</h3><div className="content-box question">{sample.text}</div><div className="evidence-answers">{[['标准标签',sample.expected],['基线预测',sample.baseline],['候选预测',sample.candidate]].map(([name,intent]) => <div key={name}><span>{name}</span><strong>{label(state,intent)}</strong><code>{intent}</code></div>)}</div><h3>候选 Top-3</h3><div className="top-intents">{sample.top3.map((intent,index) => <span key={intent}><small>0{index+1}</small>{label(state,intent)}</span>)}</div><div className="notice"><Info size={18} /><span>分类分差 {sample.margin.toFixed(5)}，是第一名与第二名的决策分值差，不是正确概率。此样本来自 {sample.sourceFile} 第 {sample.sourceRow} 条。</span></div><div className="modal-actions"><Button onClick={close}>关闭</Button><Button primary onClick={() => makeAction(sample)}><Plus size={15} />建立关联优化任务</Button></div></div>}</Modal>; }

function KnowledgeEditor({ policy, close, submit }: { policy: Knowledge | null; close: () => void; submit: (policy: Knowledge, content: string) => Promise<void> }) {
  const [content, setContent] = useState(''); const [pending,setPending] = useState(false); const [error,setError] = useState('');
  useEffect(() => { if (policy) { setContent(policy.content); setError(''); } }, [policy]);
  return <Modal open={!!policy} onClose={() => !pending && close()} title={`编辑：${policy?.title || ''}`} description={`${policy?.id || ''} · 当前 v${policy?.version || 1}，保存后创建新版本。`} wide><form onSubmit={async event => { event.preventDefault(); if (!policy) return; setPending(true); try { await submit(policy,content); } catch (problem) { setError(problem instanceof Error ? problem.message : '保存失败'); } finally { setPending(false); } }}><label className="form-field">业务知识正文<textarea className="knowledge-editor" value={content} onChange={event => setContent(event.target.value)} maxLength={4000} required /></label><div className="notice amber"><Info size={18} />请使用匿名示例或已获授权的政策。不得输入私人联系方式、凭证或未经授权的机密资料。示例政策不能直接用于生产承诺。</div>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><Button onClick={close} disabled={pending}>取消</Button><Button type="submit" primary disabled={pending || !content.trim()}>{pending ? '校验并保存…' : '安全校验并保存新版本'}</Button></div></form></Modal>;
}
